  long long count = 0;
  for (long long factor = 1; factor <= n; factor *= 10) {
    long long cur = (n / factor) % 10;
    long long higher = n / (factor * 10);
    long long lower = n % factor;
    if (cur < 2) {
      count += higher * factor;
    } else if (cur == 2) {
      count += higher * factor + lower + 1;
    } else {
      count += (higher + 1) * factor;
    }
  }
  return (int)count;
}

