class Solution:
    def numberOf2sInRange(self, n: int) -> int:
        count = 0
        factor = 1
        while factor <= n:
            cur = (n // factor) % 10
            higher = n // (factor * 10)
            lower = n % factor
            if cur < 2:
                count += higher * factor
            elif cur == 2:
                count += higher * factor + lower + 1
            else:
                count += (higher + 1) * factor
            factor *= 10
        return count

impl Solution {
  pub fn number_of2s_in_range(n: i32) -> i32 {
    let mut count: i64 = 0;
    let mut factor: i64 = 1;
    while factor <= n as i64 {
      let cur = (n as i64 / factor) % 10;
      let higher = n as i64 / (factor * 10);
      let lower = n as i64 % factor;
      if cur < 2 {
        count += higher * factor;
      } else if cur == 2 {
        count += higher * factor + lower + 1;
      } else {
        count += (higher + 1) * factor;
      }
      factor *= 10;
    }
    count as i32
  }
}

const numberOf2sInRange = (n: number): number => {
  let count = 0;
  for (let factor = 1; factor <= n; factor *= 10) {
    const cur = Math.floor(n / factor) % 10;
    const higher = Math.floor(n / (factor * 10));
    const lower = n % factor;
    if (cur < 2) count += higher * factor;
    else if (cur === 2) count += higher * factor + lower + 1;
    else count += (higher + 1) * factor;
  }
  return count;
};
